@card_GL_field : ∀ {𝔽 : Type u_1} [inst : Field 𝔽] [inst_1 : Fintype 𝔽] (n : ℕ),
  Nat.card (GL (Fin n) 𝔽) = ∏ i, (Fintype.card 𝔽 ^ n - Fintype.card 𝔽 ^ ↑i)
@Sylow.card_eq_index_normalizer : ∀ {p : ℕ} {G : Type u_1} [inst : Group G] [Fact (Nat.Prime p)] [Finite (Sylow p G)]
  (P : Sylow p G), Nat.card (Sylow p G) = (Subgroup.normalizer ↑P).index
@Subgroup.card_eq_card_quotient_mul_card_subgroup : ∀ {α : Type u_1} [inst : Group α] (s : Subgroup α),
  Nat.card α = Nat.card (α ⧸ s) * Nat.card ↥s
@Subgroup.index_mul_card : ∀ {G : Type u_1} [inst : Group G] (H : Subgroup G), H.index * Nat.card ↥H = Nat.card G

